import {DeepSeekHarness} from '@deepseek-ai/dsh-sdk-client';
import {mkdtemp,writeFile,rm} from 'node:fs/promises';import {tmpdir} from 'node:os';import {join,resolve} from 'node:path';import {fileURLToPath} from 'node:url';import assert from 'node:assert/strict';
const root=fileURLToPath(new URL('../../',import.meta.url)),dir=await mkdtemp(join(tmpdir(),'dh-skills-'));const [platform,id,token]=process.argv.slice(2);const patch=join(dir,'patch.yml');
await writeFile(patch,`- id: llm-deepseek\n  disabled: true\n- id: llm-pi-ai\n  disabled: true\n- insert:\n    - id: enterprise-tools\n      name: ${JSON.stringify(resolve(root,'dist/native/enterprise-plugin.js'))}\n    - id: fixture\n      name: ${JSON.stringify(resolve(root,'tests/fixtures/native-skills-model.mjs'))}\n`);
try{for(const prompt of ['Use evidence-review skill to review evidence.','/evidence-review review evidence']){
 const h=new DeepSeekHarness({profile:'sdk',patches:[resolve(root,'profiles/enterprise-web.patch.yml'),patch],dshHome:join(dir,Math.random().toString()),cwd:dir,processCwd:dir,provider:'skills-fixture',model:'fixture',maxTokens:1024,initializeTimeoutMs:30000,requestTimeoutMs:30000,env:{PATH:process.env.PATH,HOME:dir,TMPDIR:dir,NARB_DISABLE_NATIVE_CACHE:'1',DREAMCORE_NATIVE_BRIDGE:`${platform}/internal/v1/native-conversations/${id}/`,DREAMCORE_NATIVE_CAPABILITY:token}});
 try{const r=await h.run(prompt);assert.ok(JSON.stringify(r.events).includes('PLATFORM_SKILL_LOADED'));if(prompt.startsWith('/'))assert.ok(r.events.some(e=>e.type==='user/message'&&e.data.source?.kind==='skill-invocation'));else assert.ok(r.events.some(e=>e.type==='tool/call'&&e.data.name==='skill'||e.type==='tool/result'&&JSON.stringify(e.data).includes('Read evidence')));}finally{await h.close();}
}}finally{await rm(dir,{recursive:true,force:true});}
